const bt = K.beat * P.speed;
const H = ((P.hue % 360) + 360) % 360;
const st = ['poster','blueprint','chrome','halftone','silhouette'].indexOf(P.style) >= 0 ? P.style : 'poster';

S.rms = (S.rms || 0) * .82 + (A.rms || 0) * .18;
S.bass = (S.bass || 0) * .8 + (A.bass || 0) * .2;
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.lastBeat = K.beat;

const am = .8 + .3 * Math.sin(K.t * .31 + fr(5) * 6);
const eAmp = P.energy * (.5 + .6 * K.intensity) * am;

// thrust = clk pulse + audio (baseline carries in silence)
const thrust = clamp(.28 + .5 * K.pulse + S.rms * 1.3 + A.bass * .6 + K.intensity * .15, 0, 1.5);

const FN = clamp(P.fins, .5, 1.7);
