// ---- act dramaturgy ----
// idle : clamped engine test — violent shudder, held down, steam. (default, always in-frame)
// launch: ~18s self-contained cycle: countdown -> shudder build -> rise -> reset
// hover : retro-futurist float, thruster bob
let liftY = 0, shudder = 0, flameMul = 1, countdown = 0, steamMul = 1;
if (P.act === 'launch') {
  const per = 18 / Math.max(.2, P.speed);
  const lp = ((K.t % per) + per) % per / per;               // 0..1
  if (lp < .34) { countdown = Math.ceil((.34 - lp) / .34 * 3); shudder = (lp / .34) * (2.2 + eAmp * 2); flameMul = .4 + lp * 1.5; steamMul = 1.4; }
  else if (lp < .82) { const r = (lp - .34) / .48; liftY = -r * r * 620; flameMul = 1.7; shudder = 1.1; steamMul = 2.4 * (1 - r); }
  else { const r = (lp - .82) / .18; liftY = -620 - r * 260; flameMul = 1.4 * (1 - r); steamMul = .2; }
} else if (P.act === 'hover') {
  liftY = Math.sin(K.t * .8) * 26 + Math.sin(K.t * 1.9) * 8 - 40;
  shudder = .5 + eAmp * .6; flameMul = .9 + .5 * Math.abs(Math.sin(K.t * 5)); steamMul = .3;
} else { // idle
  shudder = 3 + eAmp * 3.2 + thrust * 1.6; flameMul = .8 + thrust * .8; steamMul = 1;
}

// shudder displacement (fast, seeded — always animates the silhouette)
const shX = (Math.sin(K.t * 27 + fr(1) * 6) + .6 * Math.sin(K.t * 41)) * shudder;
const shY = (Math.sin(K.t * 33 + fr(2) * 6)) * shudder * .5;
// whole-body slow bob + heat/wind sway (guarantees silhouette displacement in silence)
const bobV = Math.sin(K.t * .9 + fr(4) * 6) * (10 + 14 * eAmp) + K.swell * 6;
const sway = Math.sin(K.t * .5 + fr(3) * 6) * 12 * (1 + eAmp);
const rot = clamp((shX * .0016) + Math.sin(K.t * .7) * .015, -.09, .09);

// ---- geometry (design units, origin at fin base center, rocket extends up -y) ----
const bodyW = 78;
const bodyH = 250;
const noseH = 96 * TP;
const finH = 70 * FN, finW = 58 * FN;
const topY = -(bodyH + noseH);          // nose tip
const botY = 0;                          // engine bell mouth
const hw = bodyW / 2;

if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.puffs = []; for (let i = 0; i < 26; i++) S.puffs.push({ side: fr(i) < .5 ? -1 : 1, ph: fr(i + 30), sp: .4 + fr(i + 60) * .8, sz: .6 + fr(i + 90) * 1.1, dx: (fr(i + 120) - .5) });
  S.stars = []; for (let i = 0; i < 14; i++) S.stars.push({ a: fr(i + 200) * TAU, r: 1 + fr(i + 240) * 1.4, w: .3 + fr(i + 280) * .6 });
}

function bodyPath() {
  beginShape();
  vertex(0, topY);
  bezierVertex(hw * .5, topY + noseH * .25, hw, topY + noseH * .82, hw, topY + noseH);   // nose right
  vertex(hw, botY - 14);
  vertex(hw * .9, botY);                                                                  // engine skirt
  vertex(-hw * .9, botY);
  vertex(-hw, botY - 14);
  vertex(-hw, topY + noseH);
  bezierVertex(-hw, topY + noseH * .82, -hw * .5, topY + noseH * .25, 0, topY);           // nose left
  endShape(CLOSE);
}
function fin(dir) {
  beginShape();
  vertex(dir * hw * .9, botY - finH - 30);
  vertex(dir * (hw + finW), botY + 14);
  vertex(dir * hw * .95, botY - 2);
  endShape(CLOSE);
}

const ax = P.x * width + (sway + shX) * s;
const ay = P.y * height + (liftY + shY + bobV) * s;

push();
translate(ax, ay);
rotate(rot);
scale(s);

// ================= steam plumes at pad (drawn first, behind, in world-ish space) =================
if (st !== 'silhouette') {
  noStroke();
  const np = Math.floor((10 + dens * 16));
  for (let i = 0; i < np; i++) {
    const pf = S.puffs[i]; const life = ((K.t * pf.sp * .5 + pf.ph) % 1);
    const px = pf.side * (hw + 20 + life * 150) + pf.dx * 30;
    const py = botY - 6 - life * 70 + Math.sin(K.t + i) * 6;
    const sz = (20 + life * 60) * pf.sz * steamMul;
    fill(H, 4, 96, (1 - life) * 30 * steamMul);
    ellipse(px, py, sz, sz * .8);
  }
}

// ================= exhaust flame (below engine) =================
{
  const fl = (60 + thrust * 170) * flameMul;
  const fw = (30 + thrust * 26);
  noStroke();
  // outer glow
  for (let i = 4; i >= 1; i--) { const f = i / 4; fill(28, 70, 100, 10 * flameMul); ellipse(0, botY + fl * .3, fw * 2.2 * f, fl * 1.2 * f); }
  // flame tongues
  for (let i = 3; i >= 0; i--) {
    const f = i / 3;
    const flick = 1 + .35 * Math.sin(K.t * 22 + i * 2);
    const w = fw * (1 - f * .55);
    const len = fl * (1 - f * .35) * flick;
    fill(18 + f * 34, 95 - f * 45, 100, 70 + thrust * 20);
    beginShape();
    vertex(-w, botY);
    vertex(w, botY);
    vertex(w * .3, botY + len * .6);
    vertex((fr(i) - .5) * fw, botY + len);
    vertex(-w * .3, botY + len * .6);
    endShape(CLOSE);
  }
  // spark shower on strong thrust
  if (thrust > .5) for (let i = 0; i < 6; i++) { const t2 = (K.t * 2 + i / 6) % 1; fill(40, 40, 100, (1 - t2) * 60); circle((fr(i + 9) - .5) * fw * 2, botY + t2 * fl, 3); }
}

// ================= body per style =================
if (st === 'silhouette') {
  // sunburst behind
  noStroke();
  const rays = Math.floor(12 + dens * 12);
  push(); translate(0, topY + bodyH * .5);
  for (let i = 0; i < rays; i++) { const a = i / rays * TAU + K.t * .05; fill((H + 40) % 360, 60, 60, i % 2 ? 16 : 8); const L = 460; triangle(0, 0, Math.cos(a) * L, Math.sin(a) * L, Math.cos(a + .18) * L, Math.sin(a + .18) * L); }
  pop();
  fill(0, 0, 8); fin(-1); fin(1); bodyPath();
  // porthole rim of light
  fill((H + 30) % 360, 60, 70, 60); circle(0, topY + noseH + 40, 30);
  fill(0, 0, 8); circle(0, topY + noseH + 40, 20);
} else if (st === 'blueprint') {
  const LC = (H + 180) % 360;   // cyan-ish complement
  noFill();
  stroke(LC, 55, 100, 22); strokeWeight(.8); line(0, topY - 16, 0, botY + finH); // axis
  stroke(LC, 70, 100, 88); strokeWeight(1.7); fin(-1); fin(1); bodyPath();
  stroke(LC, 50, 100, 42); strokeWeight(1);
  for (let y = topY + noseH; y < botY - 20; y += 46) line(-hw, y, hw, y);           // stage rings
  ellipse(0, topY + noseH, hw * 2, 20);
  ellipse(0, topY + noseH + 40, 34, 34);                                            // porthole
  // internal tanks
  stroke(LC, 45, 100, 30); strokeWeight(.9);
  ellipse(0, topY + noseH + 110, hw * 1.1, 90); ellipse(0, topY + noseH + 200, hw * 1.1, 70);
  // dim ticks
  stroke(LC, 40, 100, 40); strokeWeight(.8);
  line(hw + 18, topY, hw + 18, botY); line(hw + 14, topY, hw + 22, topY); line(hw + 14, botY, hw + 22, botY);
  noStroke();
} else if (st === 'halftone') {
  // CMYK dot-print abstraction: build silhouette as halftone dots shaded by a light gradient
  const step = 9;
  noStroke();
  for (let y = topY; y < botY; y += step) {
    for (let x = -hw - finW; x < hw + finW; x += step) {
      let inside = false;
      if (y >= topY + noseH && y <= botY && x > -hw && x < hw) inside = true;
      else if (y < topY + noseH && y >= topY) { const w2 = hw * Math.sqrt(clamp((y - topY) / noseH, 0, 1)); if (x > -w2 && x < w2) inside = true; }
      // fins
      if (!inside && y > botY - finH - 30 && y < botY + 14) { const fx = (Math.abs(x) - hw * .9) / finW; const fy = (y - (botY - finH - 30)) / (finH + 44); if (fx > 0 && fx < 1 && fy > fx) inside = true; }
      if (!inside) continue;
      const lightx = (x + hw) / (2 * hw);             // 0 left .. 1 right
      const shade = clamp(.5 + .5 * Math.sin((lightx - .3) * Math.PI), 0, 1);
      const r = (1 - shade) * step * .7 + thrust * 1.2 * Math.sin(y * .05 + K.t * 3) * .0;
      if (r > .6) { const hh2 = (x + y) & 1; fill(hh2 ? H : (H + 20) % 360, 80, hh2 ? 90 : 100); circle(x + step * .5, y + step * .5, r); }
    }
  }
  // magenta porthole dot cluster
  fill((H + 150) % 360, 80, 90); circle(0, topY + noseH + 40, 22);
} else if (st === 'chrome') {
  // metallic vertical gradient bands + specular
  noStroke();
  fin(-1); fill(H, 30, 26); fin(1); fill(H, 30, 26);
  fill(H, 20, 30); bodyPath();
  // vertical metal banding via clipped strips
  for (let i = 0; i < 9; i++) {
    const fx = i / 8, xx = -hw + fx * bodyW;
    const b = 30 + 60 * Math.pow(Math.max(0, Math.sin(fx * Math.PI)), .6);
    fill(H, 16 - fx * 6, b, 40); rect(xx, topY + noseH, bodyW / 8, bodyH);
  }
  // specular streak
  fill(0, 0, 100, 55); rect(-hw * .5, topY + noseH, 8, bodyH * .96, 4);
  fill(0, 0, 100, 22); rect(-hw * .2, topY + noseH, 5, bodyH * .9, 3);
  // nose chrome
  fill(H, 10, 90, 40); ellipse(0, topY + noseH * .5, hw * 1.1, noseH);
  // porthole
  fill(H, 40, 20); circle(0, topY + noseH + 42, 34); fill((H + 20) % 360, 30, 80, 60); arc(0, topY + noseH + 42, 34, 34, Math.PI * 1.05, Math.PI * 1.7);
} else {
  // ================= POSTER (atomic-age screenprint) =================
  // fins — bold flat with offset registration shadow
  fill((H + 340) % 360, 80, 62); push(); translate(3, 0); fin(-1); fin(1); pop();
  fill(H, 78, 92); fin(-1); fin(1);
  // body base (nose = cream, fuselage = rectangular so color fields need no clip)
  fill(0, 0, 96); bodyPath();
  const fyTop = topY + noseH;                         // top of cylindrical fuselage
  noStroke();
  fill(H, 82, 90); rect(-hw, fyTop + bodyH * .48, bodyW, bodyH * .52); // lower half color block
  fill((H + 200) % 360, 70, 84); rect(-hw, fyTop + bodyH * .48, bodyW, 26); // teal band
  // halftone shading down the right side (screenprint tone) — bounded to fuselage rect
  fill(0, 0, 0, 26);
  for (let y = fyTop + 6; y < botY - 4; y += 8) for (let x = 6; x < hw - 3; x += 8) { const rr = (x / hw) * 4; if (rr > 1) circle(x, y, rr); }
  // racing chevrons across the upper fuselage
  fill((H + 340) % 360, 85, 70);
  for (let c = 0; c < 3; c++) { const yy = fyTop + 14 + c * 16; beginShape(); vertex(-hw * .5, yy); vertex(0, yy + 12); vertex(hw * .5, yy); vertex(hw * .5, yy + 6); vertex(0, yy + 18); vertex(-hw * .5, yy + 6); endShape(CLOSE); }
  // porthole
  fill(0, 0, 20); circle(0, topY + noseH + 46, 40);
  fill((H + 195) % 360, 65, 88); circle(0, topY + noseH + 46, 30);
  fill(0, 0, 100, 55); circle(-6, topY + noseH + 40, 9);
  stroke(H, 40, 40); strokeWeight(3); noFill(); circle(0, topY + noseH + 46, 40); noStroke();
  // rivets
  fill(0, 0, 30, 50); for (let y = topY + noseH + 6; y < botY - 8; y += 30) { circle(-hw + 7, y, 4); circle(hw - 7, y, 4); }
  // little atomic star sparkles around nose
  fill((H + 45) % 360, 70, 100);
  for (let i = 0; i < 5; i++) { const stw = S.stars[i]; const tw = .5 + .5 * Math.sin(K.t * 3 + i * 1.7); const rx = Math.cos(stw.a) * (hw + 40), ry = topY + noseH * .4 + Math.sin(stw.a) * 50; push(); translate(rx, ry); rotate(K.t * .3 + i); const rr = 4 + tw * 4; beginShape(); for (let k = 0; k < 8; k++) { const a = k / 8 * TAU, rad = k % 2 ? rr : rr * .4; vertex(Math.cos(a) * rad, Math.sin(a) * rad); } endShape(CLOSE); pop(); }
}

